package equivalent;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

class ClonePair10319DifferenceFindingTest {

    private final ClonePair10319 subject = new ClonePair10319();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: return_value.
     * Difference manifestation: the methods return different values.
     */
    @Test
    @BehavioralDifference(DifferenceType.RETURN_VALUE)
    void methodsOrderSupplementaryCharactersDifferently() {
        // method1 compares Unicode code points, so U+1F600 sorts after U+FFFD,
        // whereas method2 compares UTF-16 code units, so the high surrogate U+D83D sorts before U+FFFD.
        String supplementaryCharacter = "\uD83D\uDE00";
        String replacementCharacter = "\uFFFD";

        assertEquals(1, subject.method1(supplementaryCharacter, replacementCharacter));
        assertEquals(-1, subject.method2(supplementaryCharacter, replacementCharacter));
    }
}
